export const getSendChatMessageUrl = (roomId: number,) => {




  return `/api/chat/${roomId}`
}

/**
 * @summary Send a chat message
 */
export const sendChatMessage = async (roomId: number,
    chatInput: ChatInput, options?: RequestInit): Promise<ChatMessage> => {

  return customFetch<ChatMessage>(getSendChatMessageUrl(roomId),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(
      chatInput,)
  }
);}




